import{bV as i,aL as a,u as o,G as e}from"./chunks/framework.BfzMay2U.js";const b=JSON.parse('{"title":"5年职业规划和奋斗目标","description":"","frontmatter":{"title":"5年职业规划和奋斗目标","date":"2026-08-24T12:01:01.000Z","sticky":1,"sidebarSort":1},"headers":[],"relativePath":"java/five-year-plan.md","filePath":"java/five-year-plan.md"}'),t={name:"java/five-year-plan.md"};function r(h,l,u,c,p,n){return a(),o("div",null,[...l[0]||(l[0]=[e('<h1 id="_5年职业规划和奋斗目标" tabindex="-1">5年职业规划和奋斗目标 <a class="header-anchor" href="#_5年职业规划和奋斗目标" aria-label="Permalink to &quot;5年职业规划和奋斗目标&quot;">​</a></h1><p>2026-08-20 正式离职</p><p>下一阶段的奋斗目标</p><ol><li>系统性学习<code>java</code>系列和<code>C</code>系列</li><li>写一段好的自我介绍，并在家练习口述，保证不断断续续且不结巴</li><li>完善简历，向<code>java</code>和<code>c</code>方向靠拢</li><li>提高技术领域深度，逐渐向架构师或者嵌入式领域发展</li><li>提高对行业发展的认知以及常见的公司人员福利待遇</li></ol><p><strong>任何行业，低端岗位都是青春饭！</strong></p><blockquote><p>目标：</p><ol><li>高级程序员5 年以上，15k-30k之间</li><li>架构师级别和资深码农，25k-40k</li></ol></blockquote><h2 id="快速学习的秘诀" tabindex="-1">快速学习的秘诀 <a class="header-anchor" href="#快速学习的秘诀" aria-label="Permalink to &quot;快速学习的秘诀&quot;">​</a></h2><ul><li>听得懂，敲代码</li><li>听不懂，也要敲代码，敲着敲着就明白了</li><li>实战学习，敲代码</li></ul><blockquote><p>量变引起质变</p></blockquote><h2 id="java-基础的四种能力" tabindex="-1">java 基础的四种能力 <a class="header-anchor" href="#java-基础的四种能力" aria-label="Permalink to &quot;java 基础的四种能力&quot;">​</a></h2><ul><li>代码能力</li><li>面向对象的分析能力 <ul><li>类和对象</li><li>内存分析和垃圾回收机制</li><li>this、static</li><li>package、import</li></ul></li><li>内存底层和源码分析习惯</li><li>调试和查错能力</li></ul><h2 id="程序的本质" tabindex="-1">程序的本质 <a class="header-anchor" href="#程序的本质" aria-label="Permalink to &quot;程序的本质&quot;">​</a></h2><p>程序就是逻辑思维的表达</p><blockquote><p>任何程序本质有三个：变量、if 语句、循环语句</p></blockquote><h2 id="数据存储" tabindex="-1">数据存储 <a class="header-anchor" href="#数据存储" aria-label="Permalink to &quot;数据存储&quot;">​</a></h2><p>数据的本质就是一张张表格</p><h2 id="好的简历怎么写" tabindex="-1">好的简历怎么写 <a class="header-anchor" href="#好的简历怎么写" aria-label="Permalink to &quot;好的简历怎么写&quot;">​</a></h2><blockquote><p>1 一个原则</p><p>6 个要点</p></blockquote><h3 id="一个原则" tabindex="-1">一个原则 <a class="header-anchor" href="#一个原则" aria-label="Permalink to &quot;一个原则&quot;">​</a></h3><p>简历必须一字一字自己写，不能抄</p><ul><li>连简历都不愿意好好写，你的求职态度有问题</li><li>很多面试问题来源于简历</li></ul><h3 id="_6-个要点" tabindex="-1">6 个要点 <a class="header-anchor" href="#_6-个要点" aria-label="Permalink to &quot;6 个要点&quot;">​</a></h3><ol><li><p>基本情况介绍</p><ol><li>姓名</li><li>性别</li><li>学历</li><li>专业</li><li>联系方式，手机号码不能写错！</li></ol></li><li><p>求职意向</p><ol><li>清晰的岗位要求</li><li>工作地点</li><li>薪资要求，一般写面议，当面聊</li></ol></li><li><p>专业技能</p><ol><li>工整</li><li>有条理的罗列自己的专业技能，基本写熟练掌握即可</li><li>每列一个要想一想自己会不会，不会仔细想一想</li></ol></li><li><p>工作经验和项目经验（一份好的简历的核心）</p><ol><li>详细的工作履历</li><li>项目经验，项目通常写 3-5 个 <ol><li>项目名称</li><li>开发周期</li><li>项目描述</li><li>项目环境和技术选型</li><li>项目职责描述</li></ol></li></ol></li><li><p>曾获得奖励（可选）</p><ol><li>罗列一些和工作学习相关的奖励</li></ol></li><li><p>自我评价（可选）</p><ol><li>突出和工作相关的自我特质和优点</li><li>不要写自己的个性特点之类的东西</li></ol><blockquote><ol><li>有过项目管理经验，熟悉软件项目开发中的总体流程环节与项目分工，具备沟通协调能力，在项目遇到问题后能积极主动组织相关同事解决问题。</li><li>具备一定的英语阅读能力，在学习一些技术特性时习惯查看官方文档及说明，在阅读中加深个人理解。</li><li>适应能力强，能够很快适应新的工作环境；保持对新事物新知识的好奇心，善于总结知识点之间的关联。</li><li>具备工作中问题的解决能力，在处理工作量大的任务能够理清工作脉络，对各类需求依据重要程度与项目周期进行量化分析，按照计划推进，保障高质量交付。</li></ol></blockquote></li></ol><h2 id="面试前准备" tabindex="-1">面试前准备 <a class="header-anchor" href="#面试前准备" aria-label="Permalink to &quot;面试前准备&quot;">​</a></h2><blockquote><p>知己知彼百战百胜</p></blockquote><p>三大步适用范围：</p><ol><li>针对中小型公司</li><li>如果阿里等特大型公司，不适合。功夫在平时正常发挥即可。</li></ol><h3 id="了解该公司的基本情况" tabindex="-1">了解该公司的基本情况 <a class="header-anchor" href="#了解该公司的基本情况" aria-label="Permalink to &quot;了解该公司的基本情况&quot;">​</a></h3><ul><li>公司所在的行业是否有前景</li><li>公司历史和结构</li><li>公司产品和项目有哪些</li></ul><h3 id="侧重哪一块技术-重点复现" tabindex="-1">侧重哪一块技术，重点复现 <a class="header-anchor" href="#侧重哪一块技术-重点复现" aria-label="Permalink to &quot;侧重哪一块技术，重点复现&quot;">​</a></h3><ul><li>根据招聘信息、网上搜索公司相关的面试</li></ul><h3 id="研究该公司产品-提出问题" tabindex="-1">研究该公司产品，提出问题 <a class="header-anchor" href="#研究该公司产品-提出问题" aria-label="Permalink to &quot;研究该公司产品，提出问题&quot;">​</a></h3><ul><li>用户群体</li><li>PC 端功能研究</li><li>APP 端功能研究</li><li>对比同类产品有哪些（有哪些同类型的产品、哪些功能值得借鉴）</li></ul><blockquote><p>只要上述步骤做了之后，技术没什么硬伤，会增加 2 成概率成功</p></blockquote><h2 id="面试官喜欢什么样的人" tabindex="-1">面试官喜欢什么样的人 <a class="header-anchor" href="#面试官喜欢什么样的人" aria-label="Permalink to &quot;面试官喜欢什么样的人&quot;">​</a></h2><ol><li>秉性良好、谈吐正常的人 <ol><li>精心准备自我介绍（突出实践经验、而不是爱好）</li><li>交谈大方，无小动作</li><li>衣着干净整洁</li><li>懂得感恩。不说公司、老师、老板、同事的坏话</li></ol></li><li>工作态度端正、工作认真的人 <ol><li>是否一切以公司事务为重</li><li>加班问题，只要不影响身体的加班，都是可以接受的</li><li>大大方方谈薪水（接受薪水不是越低越好），要符合对方的预期，要高了可以给别人砍价的空间</li></ol></li><li>热爱本职业，有合理的职业规划 <ol><li>工作会不会给你带来快乐</li><li>至少规划 3 年职业规划，注意合理（不放大，也不缩小）</li></ol></li><li>热爱学习，喜欢提升自己的人 <ol><li>参加和本职工作，相关的培训（利用业务时间，周末和晚上）</li><li>最近对 xxx 新技术感兴趣，正在研究</li></ol></li></ol><h2 id="技术面试中-不该问的四大问题" tabindex="-1">技术面试中，不该问的四大问题 <a class="header-anchor" href="#技术面试中-不该问的四大问题" aria-label="Permalink to &quot;技术面试中，不该问的四大问题&quot;">​</a></h2><blockquote><p>40 分钟面试即将结束，面试官最后问你：“你有什么问题问我吗？”</p></blockquote><p>重要，但没必要在技术面试中问的问题：</p><ul><li>我能拿多少工资？</li><li>公司经常加班吗？</li><li>您觉得我们今天能面上吗？</li><li>五险一金有没有？交通补助有没有？</li></ul><blockquote><p>这些问题不是不重要，没必要在技术面试中问。可以和人事详细沟通。</p></blockquote><ul><li><p>技术面试中，问一个和技术先关的问题，如果能和对方公司现有业务结合起来，最好。你们公司有什么样的技术架构啊？为什么选择它啊？</p></li><li><p>又不用你回答，还能给你加分。何乐而不为呢？</p></li></ul><h2 id="职场成功的核武器" tabindex="-1">职场成功的核武器 <a class="header-anchor" href="#职场成功的核武器" aria-label="Permalink to &quot;职场成功的核武器&quot;">​</a></h2><p>硬实力和软实力都很重要</p><ul><li><p>程序员的硬实力：技术能力</p></li><li><p>程序员的软实力：人际沟通、协作、管理能力</p></li></ul><blockquote><p>硬实力</p><ul><li>职场的基础</li><li>小白重视</li><li>难以短时间提高</li><li>硬实力更多的是影响工作</li></ul></blockquote><blockquote><p>软实力：沟通、管理能力</p><ul><li>职场晋升的关键</li><li>破除：观念认可是天生不可改变，大多数忽视训练</li><li>短时间可以迅速提高</li><li>软实力，影响工作和人生的方方面面</li></ul></blockquote><h3 id="软实力理论" tabindex="-1">软实力理论 <a class="header-anchor" href="#软实力理论" aria-label="Permalink to &quot;软实力理论&quot;">​</a></h3><p>人的软实力有 7 种能力组成：</p><ul><li>基础实力（形象气质、声音魅力）决定：你的人生基础（婚姻、朋友圈）</li><li>人际沟通（沟通力、说服力）决定：能否晋升职场中层</li><li>领导能力（影响力、领导力、情商）决定：能否晋升到职场高层</li></ul><blockquote><p>适用范围：有某项特长能力的人不适用本理论</p></blockquote><ul><li>软实力决定人生高度</li><li>软实力可以训练，快速提高</li><li>软实力短板，决定你的发展</li><li>追求综合，不追求某一项特牛</li></ul><h3 id="形象气质测试" tabindex="-1">形象气质测试 <a class="header-anchor" href="#形象气质测试" aria-label="Permalink to &quot;形象气质测试&quot;">​</a></h3><ol><li>早晨起床花多长时间打理形象</li><li>多久进一次理发店</li><li>形象气质是否先天还是后天形成</li><li>形象礼仪在社交中的重要性，非常重要</li></ol><h3 id="声音魅力测试" tabindex="-1">声音魅力测试 <a class="header-anchor" href="#声音魅力测试" aria-label="Permalink to &quot;声音魅力测试&quot;">​</a></h3><ol><li>微信发语音时，听听自己的声音，如何评价自己的声音？</li><li>有没人夸赞过你的声音有魅力？</li><li>唱歌或者大声说话使用哪种方式呼吸？</li></ol><h3 id="沟通力测试" tabindex="-1">沟通力测试 <a class="header-anchor" href="#沟通力测试" aria-label="Permalink to &quot;沟通力测试&quot;">​</a></h3><ul><li>好的沟通，让你有好的人际关系</li><li>不沟通，没朋友，没伙伴</li><li>错误沟通，让你丢失伙伴，丢失爱人</li></ul><ol><li>沟通中，能否正确觉知他人的情绪？</li><li>表达中，自我感觉给别人留下的印象是？</li><li>如果你不赞同岳母的意见，如何反馈？</li><li>沟通力是先天还是后天形成？</li></ol><h3 id="说服力测试" tabindex="-1">说服力测试 <a class="header-anchor" href="#说服力测试" aria-label="Permalink to &quot;说服力测试&quot;">​</a></h3><p>人的一生中，每时每刻都在说服别人，被别人说服。</p><ol><li>你要建立个团队，你能说服多少人跟随你？</li><li>加入新团队中，多长时间得到大家的认同？</li><li>新认识一位女神（男神），多久可以约到他（她）吃饭或者看电影？</li></ol><h3 id="影响力测试" tabindex="-1">影响力测试 <a class="header-anchor" href="#影响力测试" aria-label="Permalink to &quot;影响力测试&quot;">​</a></h3><ol><li>多少人认识你？</li><li>曾经在多少人面前表达自己的想法？</li></ol><h3 id="领导力测试" tabindex="-1">领导力测试 <a class="header-anchor" href="#领导力测试" aria-label="Permalink to &quot;领导力测试&quot;">​</a></h3><ol><li>你管理过的最大的团队多少人？</li><li>团队的执行程度？</li><li>作为领导，下属多长时间可以领会你的意图？</li></ol><h3 id="情商测试" tabindex="-1">情商测试 <a class="header-anchor" href="#情商测试" aria-label="Permalink to &quot;情商测试&quot;">​</a></h3><blockquote><p>情商不是见人说人话，见鬼说鬼话。</p><p>情商是面对逆境时，情绪控制能力。</p></blockquote><ol><li>遇到让你生气的场景，多久可以平复情绪？</li><li>假设项目一周后上线，需要这一周通宵加班，你如何处理？</li><li>面临重大挫折，如何处理？</li></ol><hr><ul><li><p>标准版 javase</p></li><li><p>企业版 javaee</p></li><li><p>微型版 javame</p></li></ul><p>目前企业界流行的 java 的版本是 JAVA8</p><p>JAVA的核心优势是跨平台</p>',73)])])}const q=i(t,[["render",r]]);export{b as __pageData,q as default};
